GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """
    Greedy + local search. Sort models by req_rate/slo descending, place each
    on the GPU where the resulting KVPR is lowest (memory must remain > 0).
    Then improve with moves and swaps between GPUs whenever the global max
    KVPR strictly decreases.
    """

    placement = {g: [] for g in range(gpu_num)}
    free = [GPU_MEM_SIZE] * gpu_num
    load = [0.0] * gpu_num

    def cur_max():
        return max((load[g] / free[g] for g in range(gpu_num) if free[g] < GPU_MEM_SIZE),
                   default=0.0)

    for m in sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True):
        w = m.req_rate / m.slo
        best, best_r = None, float('inf')
        for g in range(gpu_num):
            nf = free[g] - m.model_size
            if nf > 0:
                r = (load[g] + w) / nf
                if r < best_r:
                    best, best_r = g, r
        if best is None:
            for g in range(gpu_num):
                if free[g] >= m.model_size:
                    best = g
                    break
        if best is None:
            raise ValueError(f"Cannot place model of size {m.model_size} GB")
        placement[best].append(m)
        load[best] += w
        free[best] -= m.model_size

    # Local search: moves, then swaps, until no improvement
    improved = True
    while improved:
        improved = False
        mx = cur_max()
        for src in range(gpu_num):
            for m in list(placement[src]):
                w = m.req_rate / m.slo
                for dst in range(gpu_num):
                    if dst == src or free[dst] - m.model_size <= 0:
                        continue
                    load[src] -= w; free[src] += m.model_size
                    load[dst] += w; free[dst] -= m.model_size
                    if cur_max() < mx - 1e-12:
                        placement[src].remove(m); placement[dst].append(m)
                        improved = True
                        break
                    load[src] += w; free[src] -= m.model_size
                    load[dst] -= w; free[dst] += m.model_size
                if improved:
                    break
            if improved:
                break
        if improved:
            continue
        hot = max((g for g in range(gpu_num) if placement[g]),
                  key=lambda g: load[g] / free[g], default=None)
        if hot is None:
            break
        for m in list(placement[hot]):
            w1 = m.req_rate / m.slo
            for dst in range(gpu_num):
                if dst == hot:
                    continue
                for m2 in list(placement[dst]):
                    w2 = m2.req_rate / m2.slo
                    if (free[hot] + m.model_size - m2.model_size <= 0 or
                            free[dst] + m2.model_size - m.model_size <= 0):
                        continue
                    load[hot] += w2 - w1; free[hot] += m.model_size - m2.model_size
                    load[dst] += w1 - w2; free[dst] += m2.model_size - m.model_size
                    if cur_max() < mx - 1e-12:
                        placement[hot].remove(m); placement[hot].append(m2)
                        placement[dst].remove(m2); placement[dst].append(m)
                        improved = True
                        break
                    load[hot] -= w2 - w1; free[hot] -= m.model_size - m2.model_size
                    load[dst] -= w1 - w2; free[dst] -= m2.model_size - m.model_size
                if improved:
                    break
            if improved:
                break

    return placement

